import React, { useEffect, useRef } from 'react';
import './NiftyChart.css';

const NiftyChart = () => {
  const containerRef = useRef();

  useEffect(() => {
    const current = containerRef.current;
    if (!current) return;

    // Clear previous widget if it exists (for React 18 strict mode double-mounts)
    current.innerHTML = '';

    // Create and append TradingView widget script with inline JSON config
    const script = document.createElement('script');
    script.src = 'https://s3.tradingview.com/external-embedding/embed-widget-mini-symbol-overview.js';
    script.async = true;
    script.crossOrigin = 'anonymous';
    script.textContent = JSON.stringify({
      symbol: 'NSE:NIFTY',
      width: '100%',
      height: '350',
      locale: 'en_IN',
      dateRange: '1M',
      colorTheme: 'light',
      trendLineColor: '#14C4B5',
      underLineColor: 'rgba(20, 196, 181, 0.3)',
      underLineBottomColor: 'rgba(20, 196, 181, 0)',
      isTransparent: false,
      autosize: false,
      largeChartUrl: ''
    });
    script.onload = () => {
      console.log('TradingView widget loaded successfully');
    };
    script.onerror = (event) => {
      console.error('TradingView widget failed to load', event);
    };
    current.appendChild(script);

    return () => {
      if (current) {
        current.innerHTML = '';
      }
    };
  }, []);

  return (
    <div className="chart-widget-block">
      {/* Updated the title to be explicitly clear it is the Indian market */}
      <h3 className="chart-title">India Market: NIFTY 50</h3>
      <div ref={containerRef} className="chart-embed"></div>
    </div>
  );
};

export default NiftyChart;
